CREATE TABLE IF NOT EXISTS hospital (
 hpId BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,picture VARCHAR(200),telephone VARCHAR(30),address VARCHAR(200),businessHours VARCHAR(120),deadline VARCHAR(80),rule VARCHAR(30),state INT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (
 userId VARCHAR(11) PRIMARY KEY,password VARCHAR(100) NOT NULL,realName VARCHAR(40) NOT NULL,sex INT NOT NULL,birthday DATE NOT NULL,identityCard VARCHAR(18) NOT NULL,userType INT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS doctor (
 docId BIGINT PRIMARY KEY AUTO_INCREMENT,docCode VARCHAR(30) NOT NULL UNIQUE,realName VARCHAR(40) NOT NULL,password VARCHAR(100) NOT NULL,sex INT DEFAULT 1,deptno INT DEFAULT 1,hpId BIGINT,role VARCHAR(20) NOT NULL DEFAULT 'DOCTOR',state INT NOT NULL DEFAULT 1,
 FOREIGN KEY(hpId) REFERENCES hospital(hpId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS person (
 personId BIGINT PRIMARY KEY AUTO_INCREMENT,userId VARCHAR(11) NOT NULL,realName VARCHAR(40) NOT NULL,sex INT NOT NULL,birthday DATE NOT NULL,identityCard VARCHAR(18) NOT NULL,identityHash CHAR(64) NOT NULL,relationship VARCHAR(20) NOT NULL,isSelf BOOLEAN NOT NULL DEFAULT FALSE,state INT NOT NULL DEFAULT 1,
 UNIQUE KEY uq_person_owner_identity(userId,identityHash),FOREIGN KEY(userId) REFERENCES users(userId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS setmeal (
 smId BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,type INT NOT NULL,price DECIMAL(10,2) NOT NULL,state INT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS checkitem (
 ciId BIGINT PRIMARY KEY AUTO_INCREMENT,ciName VARCHAR(100) NOT NULL,ciContent VARCHAR(300) NOT NULL,meaning VARCHAR(300),remarks VARCHAR(300),state INT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS checkitemdetailed (
 cdId BIGINT PRIMARY KEY AUTO_INCREMENT,ciId BIGINT NOT NULL,name VARCHAR(100) NOT NULL,unit VARCHAR(40),minrange DECIMAL(16,4),maxrange DECIMAL(16,4),normalValue DECIMAL(16,4),normalValueString VARCHAR(200),type INT NOT NULL DEFAULT 1,required BOOLEAN NOT NULL DEFAULT TRUE,remarks VARCHAR(300),state INT NOT NULL DEFAULT 1,
 FOREIGN KEY(ciId) REFERENCES checkitem(ciId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS setmealdetailed (
 sdId BIGINT PRIMARY KEY AUTO_INCREMENT,smId BIGINT NOT NULL,ciId BIGINT NOT NULL,
 UNIQUE KEY uq_meal_item(smId,ciId),FOREIGN KEY(smId) REFERENCES setmeal(smId),FOREIGN KEY(ciId) REFERENCES checkitem(ciId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hospital_setmeal (
 hpId BIGINT NOT NULL,smId BIGINT NOT NULL,PRIMARY KEY(hpId,smId),FOREIGN KEY(hpId) REFERENCES hospital(hpId),FOREIGN KEY(smId) REFERENCES setmeal(smId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS appointment_schedule (
 hpId BIGINT NOT NULL,appointmentDate DATE NOT NULL,capacity INT NOT NULL DEFAULT 0,used INT NOT NULL DEFAULT 0,PRIMARY KEY(hpId,appointmentDate),FOREIGN KEY(hpId) REFERENCES hospital(hpId),CHECK(capacity>=0 AND used>=0 AND capacity>=used)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (
 orderId BIGINT PRIMARY KEY AUTO_INCREMENT,userId VARCHAR(11) NOT NULL,personId BIGINT NOT NULL,hpId BIGINT NOT NULL,smId BIGINT NOT NULL,orderDate DATE NOT NULL,state INT NOT NULL DEFAULT 1,requestId VARCHAR(64) NOT NULL,
 identityHash CHAR(64) NOT NULL,activeIdentity CHAR(64) GENERATED ALWAYS AS (CASE WHEN state=1 THEN identityHash ELSE NULL END) STORED,
 personName VARCHAR(40) NOT NULL,personSex INT NOT NULL,personBirthday DATE NOT NULL,personIdentityMasked VARCHAR(30) NOT NULL,hospitalName VARCHAR(100) NOT NULL,hospitalAddress VARCHAR(200),hospitalTelephone VARCHAR(30),businessHours VARCHAR(120),deadline VARCHAR(80),setmealName VARCHAR(100) NOT NULL,amount DECIMAL(10,2) NOT NULL,
 reportVersion INT NOT NULL DEFAULT 0,reportStarted BOOLEAN NOT NULL DEFAULT FALSE,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,archivedAt TIMESTAMP NULL,
 UNIQUE KEY uq_order_request(userId,requestId),UNIQUE KEY uq_order_active_identity(activeIdentity),KEY ix_order_hospital_date(hpId,orderDate,state),KEY ix_order_user(userId,state),
 FOREIGN KEY(userId) REFERENCES users(userId),FOREIGN KEY(personId) REFERENCES person(personId),FOREIGN KEY(hpId) REFERENCES hospital(hpId),FOREIGN KEY(smId) REFERENCES setmeal(smId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cireport (
 cirId BIGINT PRIMARY KEY AUTO_INCREMENT,orderId BIGINT NOT NULL,ciId BIGINT NOT NULL,ciName VARCHAR(100) NOT NULL,
 UNIQUE KEY uq_report_order_item(orderId,ciId),FOREIGN KEY(orderId) REFERENCES orders(orderId),FOREIGN KEY(ciId) REFERENCES checkitem(ciId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cidetailedreport (
 cidrId BIGINT PRIMARY KEY AUTO_INCREMENT,cirId BIGINT NOT NULL,orderId BIGINT NOT NULL,sourceDetailId BIGINT NOT NULL,name VARCHAR(100) NOT NULL,unit VARCHAR(40),minrange DECIMAL(16,4),maxrange DECIMAL(16,4),normalValue DECIMAL(16,4),normalValueString VARCHAR(200),type INT NOT NULL,required BOOLEAN NOT NULL DEFAULT TRUE,value VARCHAR(500),isError INT NOT NULL DEFAULT 0,
 UNIQUE KEY uq_report_detail(orderId,sourceDetailId),FOREIGN KEY(cirId) REFERENCES cireport(cirId),FOREIGN KEY(orderId) REFERENCES orders(orderId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS overallresult (
 orId BIGINT PRIMARY KEY AUTO_INCREMENT,orderId BIGINT NOT NULL,title VARCHAR(100) NOT NULL,content VARCHAR(1000) NOT NULL,FOREIGN KEY(orderId) REFERENCES orders(orderId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment (
 paymentId BIGINT PRIMARY KEY AUTO_INCREMENT,orderId BIGINT NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,channel VARCHAR(20) NOT NULL DEFAULT 'DEMO',status VARCHAR(20) NOT NULL DEFAULT 'PAID',createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,refundedAt TIMESTAMP NULL,FOREIGN KEY(orderId) REFERENCES orders(orderId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS seed_history (
 seedKey VARCHAR(80) PRIMARY KEY,createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
